// src/main/autoNotes.js
//
// One deterministic sentence summarizing a lead — "Good lead. Strong
// reviews but outdated website. Recommend redesign." Built purely from
// data already computed (score, opportunities), template-filled, not
// generated by any AI/LLM (hard constraint for this app).

function qualifierFor(total) {
  if (total >= 90) return 'Excellent lead.';
  if (total >= 80) return 'Strong lead.';
  if (total >= 70) return 'Good lead.';
  if (total >= 60) return 'Marginal lead.';
  return 'Low-priority lead.';
}

function shortServiceName(name) {
  return (name || '')
    .replace('Website Redesign', 'redesign')
    .replace('Website Design + AI Booking Assistant', 'a website build')
    .replace('Mobile-Responsive Rebuild', 'a mobile rebuild')
    .replace('Website Security Fix', 'a security fix')
    .replace('Website Performance Optimization', 'performance optimization')
    .replace('Booking System', 'a booking system')
    .replace('AI Chat Assistant', 'live chat')
    .replace('Analytics & Tracking Setup', 'analytics setup')
    .replace('CRM Setup', 'a CRM')
    .replace('Email Marketing Setup', 'email marketing')
    .replace('Reputation & Review Growth Package', 'a review-growth push')
    .replace('SEO Fundamentals Package', 'SEO basics')
    .replace('SEO Structured Data Setup', 'structured data');
}

// scoring: ScoreResult, opportunities: Opportunity[] (already severity-sorted).
function generateAutoNote(lead, scoring, opportunities) {
  const qualifier = qualifierFor(scoring.total);

  const reviewCount = lead.reviewCount || 0;
  const rating = lead.rating != null ? Number(lead.rating) : null;
  let positive = null;
  if (rating != null && rating >= 4.5 && reviewCount >= 20) positive = 'Strong reviews';
  else if (reviewCount >= 50) positive = 'Well-established online presence';
  else if (reviewCount >= 5) positive = 'Some review activity';

  const topGap = (opportunities || [])[0];
  const negative = topGap ? topGap.gap.replace(/ Missing$/, '').toLowerCase() : null;

  const recommend = topGap ? shortServiceName(topGap.potentialService) : 'a general audit';

  let middle;
  if (positive && negative) middle = `${positive} but ${negative}.`;
  else if (negative) middle = `${negative[0].toUpperCase()}${negative.slice(1)}.`;
  else if (positive) middle = `${positive}.`;
  else middle = 'No major gaps or standout signals detected.';

  return `${qualifier} ${middle} Recommend ${recommend}.`;
}

module.exports = { generateAutoNote };
